import asyncio,sys,json
from h import *

SEED = """(()=>{const S=MSA.state;S.tasks=S.tasks.filter(x=>x.routine);const mk=(id,title,o)=>S.tasks.unshift(MSA.tasksApi.blank(Object.assign({id,title},o||{})));
mk('t1','مهمة أولى',{priority:'high'});mk('t2','مهمة ثانية',{due:'2030-01-05T10:00'});mk('t3','مهمة ثالثة',{status:'doing'});mk('t4','مهمة رابعة');
mk('n1','ملاحظة أولى',{type:'note',desc:'<p>نص الملاحظة</p>'});mk('n2','ملاحظة ثانية',{type:'note'});MSA.save();MSA.go('tasks')})()"""
ids = lambda pg: pg.evaluate("MSA.state.tasks.filter(x=>!x.routine).map(x=>x.id)")
sel = lambda pg: pg.evaluate("MSA.multi.ids('tasks')")

async def main():
    async with Env() as e:
        pg = await e.page(w=1200, h=800)
        await pg.evaluate(SEED); await pg.wait_for_timeout(500)
        ok('select engine loaded', await pg.evaluate("!!MSA.multi&&!!MSA.menu"))
        ok('Select button is in the page header', await pg.evaluate("!!document.querySelector('.page-head .ms-tgl')"))
        # --- ctrl / shift click
        await pg.click('.trow[data-id=t1] .tt', modifiers=['Control']); await pg.wait_for_timeout(100)
        ok('ctrl+click selects without opening the editor', await sel(pg)==['t1'] and not await pg.query_selector('.drawer'))
        await pg.click('.trow[data-id=t3] .tt', modifiers=['Control'])
        ok('ctrl+click adds a second item', set(await sel(pg))=={'t1','t3'})
        ok('selected rows are highlighted + bar shows count', await pg.evaluate("document.querySelectorAll('.trow.ms-on').length===2&&/2/.test(document.querySelector('.ms-bar .ms-n').textContent)"))
        await pg.click('.trow[data-id=t4] .tt')
        ok('plain click while selecting toggles instead of opening', set(await sel(pg))=={'t1','t3','t4'} and not await pg.query_selector('.drawer'))
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(100)
        ok('Esc clears the selection and the bar', await sel(pg)==[] and not await pg.query_selector('.ms-bar'))
        await pg.click('.trow[data-id=t1] .tt', modifiers=['Control']); await pg.click('.trow[data-id=t4] .tt', modifiers=['Shift'])
        ok('shift+click selects a range', len(await sel(pg))>=2 and 't1' in await sel(pg) and 't4' in await sel(pg), await sel(pg))
        await pg.keyboard.press('Control+a'); await pg.wait_for_timeout(100)
        ok('Ctrl+A selects every visible item', len(await sel(pg))==await pg.evaluate("[...document.querySelectorAll('.trow')].filter(r=>{const x=MSA.state.tasks.find(t=>t.id===r.dataset.id);return x&&!x.routine}).length")>=4)
        await pg.keyboard.press('Escape')
        # --- bulk actions from the bar
        await pg.click('.trow[data-id=t1] .tt', modifiers=['Control']); await pg.click('.trow[data-id=t2] .tt', modifiers=['Control'])
        await pg.click('.ms-bar [data-ms="a:done"]'); await pg.wait_for_timeout(200)
        ok('bar: mark done completes both', await pg.evaluate("['t1','t2'].every(i=>MSA.state.tasks.find(x=>x.id===i).status==='done')"))
        ok('selection survives the re-render', set(await sel(pg))=={'t1','t2'} or await sel(pg)==[] , await sel(pg))
        # priority + colour + status via menu
        await pg.evaluate("MSA.multi.clear('tasks')"); await pg.wait_for_timeout(100)
        await pg.click('.trow[data-id=t3] .tt', modifiers=['Control']); await pg.click('.trow[data-id=t4] .tt', modifiers=['Control'])
        await pg.click('.ms-bar [data-ms="a:color"]'); await pg.wait_for_selector('.fm-ctx')
        await pg.click('.fm-ctx [data-m="col:#22c55e"]'); await pg.wait_for_timeout(200)
        ok('bar: colour applies to both tasks', await pg.evaluate("['t3','t4'].every(i=>MSA.state.tasks.find(x=>x.id===i).color==='#22c55e')"))
        ok('coloured tasks show a coloured edge', await pg.evaluate("getComputedStyle(document.querySelector('.trow[data-id=t3]')).borderInlineStartColor==='rgb(34, 197, 94)'"))
        await pg.click('.ms-bar [data-ms="more"]'); await pg.wait_for_selector('.fm-ctx'); await pg.click('.fm-ctx [data-m="prio"]'); await pg.click('.fm-ctx [data-m="pr:urgent"]'); await pg.wait_for_timeout(200)
        ok('menu: priority submenu applies', await pg.evaluate("['t3','t4'].every(i=>MSA.state.tasks.find(x=>x.id===i).priority==='urgent')"))
        await pg.click('.ms-bar [data-ms="more"]'); await pg.click('.fm-ctx [data-m="due"]'); await pg.click('.fm-ctx [data-m="due:tom"]'); await pg.wait_for_timeout(200)
        tom = await pg.evaluate("(()=>{const d=new Date();d.setDate(d.getDate()+1);return MSA.u.dateKey(d)})()")
        ok('menu: due tomorrow keeps/sets a time', await pg.evaluate("t=>['t3','t4'].every(i=>MSA.state.tasks.find(x=>x.id===i).due.startsWith(t))",tom))
        await pg.click('.ms-bar [data-ms="more"]'); await pg.click('.fm-ctx [data-m="mvst"]'); await pg.click('.fm-ctx [data-m="st:review"]'); await pg.wait_for_timeout(200)
        ok('menu: move to status', await pg.evaluate("['t3','t4'].every(i=>MSA.state.tasks.find(x=>x.id===i).status==='review')"))
        # duplicate
        n0 = len(await ids(pg)); await pg.click('.ms-bar [data-ms="more"]'); await pg.click('.fm-ctx [data-m="dup"]'); await pg.wait_for_timeout(400)
        ok('duplicate makes copies with new ids', len(await ids(pg))==n0+2 and await pg.evaluate("MSA.state.tasks.filter(x=>/\\(نسخة\\)/.test(x.title)).length===2"))
        # delete with undo
        await pg.evaluate("MSA.multi.clear('tasks')"); await pg.wait_for_timeout(100)
        await pg.click('.trow[data-id=t3] .tt', modifiers=['Control']); await pg.click('.trow[data-id=t4] .tt', modifiers=['Control'])
        before = await ids(pg)
        await pg.click('.ms-bar [data-ms="a:del"]'); await pg.wait_for_selector('.overlay .mf .btn.primary'); await pg.click('.overlay .mf .btn.primary'); await pg.wait_for_timeout(300)
        ok('bulk delete removes the selected tasks', 't3' not in await ids(pg) and 't4' not in await ids(pg))
        ok('delete shows an Undo toast', await pg.evaluate("!!document.querySelector('.toast.ms-undo button')"))
        await pg.click('.toast.ms-undo button'); await pg.wait_for_timeout(300)
        ok('Undo restores them in place', await ids(pg)==before, (before, await ids(pg)))
        # --- right-click on an item
        await pg.click('.trow[data-id=t3] .tt', button='right'); await pg.wait_for_selector('.fm-ctx')
        ok('right-click opens the task menu', await pg.evaluate("[...document.querySelectorAll('.fm-ctx [data-m]')].map(b=>b.dataset.m).includes('done')||[...document.querySelectorAll('.fm-ctx [data-m]')].map(b=>b.dataset.m).includes('reopen')"))
        ok('menu stays inside the viewport', await pg.evaluate("(()=>{const r=document.querySelector('.fm-ctx').getBoundingClientRect();return r.left>=0&&r.top>=0&&r.right<=innerWidth&&r.bottom<=innerHeight})()"))
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(100)
        ok('Esc closes the menu', not await pg.query_selector('.fm-ctx'))
        # right-click on background
        await pg.click('.page-head h1', button='right'); await pg.wait_for_selector('.fm-ctx')
        ok('right-click background: new task / select all', await pg.evaluate("['newtask','newnote','all'].every(i=>!!document.querySelector('.fm-ctx [data-m=\"'+i+'\"]')))") if False else await pg.evaluate("['newtask','newnote','all'].every(i=>!!document.querySelector('.fm-ctx [data-m=\"'+i+'\"]'))"))
        await pg.click('.fm-ctx [data-m="all"]'); await pg.wait_for_timeout(200)
        ok('background menu select-all selects', len(await sel(pg))>=4)
        await pg.keyboard.press('Escape')
        # --- notes view
        await pg.evaluate("MSA.state.ui.tasksView='notes';MSA.save();MSA.rerender(false)"); await pg.wait_for_timeout(400)
        await pg.click('.ncard[data-id=n1] h4', modifiers=['Control']); await pg.click('.ncard[data-id=n2] h4', modifiers=['Control'])
        ok('notes: multi-select works', set(await sel(pg))=={'n1','n2'})
        await pg.click('.ms-bar [data-ms="a:color"]'); await pg.wait_for_selector('.fm-ctx'); n = await pg.evaluate("document.querySelectorAll('.fm-ctx [data-m^=ncol]').length")
        ok('notes: colour menu has the note palette', n==7, n)
        await pg.click('.fm-ctx [data-m="ncol:3"]'); await pg.wait_for_timeout(200)
        ok('notes: colour applies to both and renders', await pg.evaluate("['n1','n2'].every(i=>MSA.state.tasks.find(x=>x.id===i).color)&&[...document.querySelectorAll('.ncard')].every(c=>c.style.getPropertyValue('--ncol'))"))
        await pg.click('.ms-bar [data-ms="more"]'); await pg.click('.fm-ctx [data-m="pin"]'); await pg.wait_for_timeout(200)
        ok('notes: pin', await pg.evaluate("['n1','n2'].every(i=>MSA.state.tasks.find(x=>x.id===i).pinned)"))
        await pg.click('.ms-bar [data-ms="more"]'); await pg.click('.fm-ctx [data-m="conv"]'); await pg.wait_for_timeout(300)
        ok('notes: convert to tasks', await pg.evaluate("['n1','n2'].every(i=>MSA.state.tasks.find(x=>x.id===i).type==='task')"))
        await pg.evaluate("MSA.state.ui.tasksView='board';MSA.save();MSA.rerender(false)"); await pg.wait_for_timeout(400)
        ok('board: cards are selectable', await pg.evaluate("document.querySelectorAll('.kcard.ms-item').length>=3"))
        await pg.click('.kcard[data-id=t1] .tt, .kcard[data-id=t1]', modifiers=['Control'], position={'x':20,'y':10}); await pg.wait_for_timeout(150)
        ok('board: ctrl+click selects a card', 't1' in await sel(pg))
        await pg.keyboard.press('Escape')

        # ---- projects: active tabs + completed cards
        await pg.evaluate("""(()=>{const S=MSA.state;S.projects=[];const mk=(id,name,o)=>S.projects.push(Object.assign({id,name,created:Date.now(),status:'active',steps:[]},o||{}));
          mk('p1','مشروع أ');mk('p2','مشروع ب');mk('p3','مشروع ج');mk('p4','مشروع منتهي',{status:'done',completedAt:Date.now(),client:'عميل س'});mk('p5','مشروع منتهي 2',{status:'done',completedAt:Date.now()-1e5});
          S.ui.project='p1';MSA.save();MSA.go('active')})()"""); await pg.wait_for_timeout(500)
        await pg.mouse.click(5,5); await pg.keyboard.press('Control+a'); await pg.keyboard.press('Delete'); await pg.wait_for_timeout(200)
        ok('projects: Ctrl+A / Del do not hijack the page (board keys keep working)', await pg.evaluate("MSA.multi.ids('proj-active').length===0&&!document.querySelector('.overlay')"))
        await pg.click('.ptab[data-id=p2]', modifiers=['Control']); await pg.click('.ptab[data-id=p3]', modifiers=['Control']); await pg.wait_for_timeout(100)
        ok('projects: ctrl+click selects tabs without switching project', set(await pg.evaluate("MSA.multi.ids('proj-active')"))=={'p2','p3'} and await pg.evaluate("MSA.state.ui.project")=='p1')
        await pg.click('.ms-bar [data-ms="a:color"]'); await pg.wait_for_selector('.fm-ctx'); await pg.click('.fm-ctx [data-m="col:#3b82f6"]'); await pg.wait_for_timeout(200)
        ok('projects: colour applies and shows on tabs', await pg.evaluate("['p2','p3'].every(i=>MSA.state.projects.find(x=>x.id===i).color==='#3b82f6')&&getComputedStyle(document.querySelector('.ptab[data-id=p2]')).boxShadow!=='none'"))
        await pg.click('.ptab[data-id=p1]', button='right'); await pg.wait_for_selector('.fm-ctx')
        ok('projects: right-click menu has complete/client/colour/delete', await pg.evaluate("['complete','client','color','del'].every(i=>!!document.querySelector('.fm-ctx [data-m=\"'+i+'\"]'))"))
        await pg.keyboard.press('Escape')
        await pg.keyboard.press('Escape'); await pg.evaluate("MSA.multi.clear('proj-active')")
        await pg.click('.ptab[data-id=p2]', modifiers=['Control']); await pg.click('.ptab[data-id=p3]', modifiers=['Control'])
        await pg.click('.ms-bar [data-ms="a:complete"]'); await pg.wait_for_selector('.overlay .mf .btn.primary'); await pg.click('.overlay .mf .btn.primary'); await pg.wait_for_timeout(400)
        ok('projects: bulk complete moves both to Completed', await pg.evaluate("['p2','p3'].every(i=>MSA.state.projects.find(x=>x.id===i).status==='done')"))
        await pg.evaluate("MSA.go('done')"); await pg.wait_for_timeout(500)
        await pg.evaluate("MSA.state.ui.doneView='all';MSA.state.ui.doneClient=null;MSA.rerender(false)"); await pg.wait_for_timeout(400)
        ok('done: cards are selectable items', await pg.evaluate("document.querySelectorAll('.pcard.ms-item').length>=4"))
        await pg.click('.pcard[data-id=p2] h3', modifiers=['Control']); await pg.click('.pcard[data-id=p3] h3', modifiers=['Control']); await pg.wait_for_timeout(100)
        ok('done: ctrl+click selects without opening the project', set(await pg.evaluate("MSA.multi.ids('proj-done')"))=={'p2','p3'} and await pg.evaluate("!MSA.state.ui.doneOpen"))
        await pg.click('.ms-bar [data-ms="a:reopen"]'); await pg.wait_for_selector('.overlay .mf .btn.primary'); await pg.click('.overlay .mf .btn.primary'); await pg.wait_for_timeout(300)
        ok('done: bulk reopen returns them to active', await pg.evaluate("['p2','p3'].every(i=>MSA.state.projects.find(x=>x.id===i).status==='active')"))
        await pg.evaluate("MSA.go('done')"); await pg.wait_for_timeout(400)
        await pg.evaluate("MSA.state.ui.doneView='all';MSA.state.ui.doneClient=null;MSA.rerender(false)"); await pg.wait_for_timeout(400)
        await pg.click('.pcard[data-id=p4] h3', button='right'); await pg.wait_for_selector('.fm-ctx')
        ok('done: right-click menu has present/reopen/delete', await pg.evaluate("['present','reopen','del'].every(i=>!!document.querySelector('.fm-ctx [data-m=\"'+i+'\"]'))"))
        await pg.click('.fm-ctx [data-m="del"]'); await pg.wait_for_selector('.overlay .mf .btn.primary'); await pg.click('.overlay .mf .btn.primary'); await pg.wait_for_timeout(300)
        ok('done: delete from the menu removes the project', await pg.evaluate("!MSA.state.projects.find(x=>x.id==='p4')"))
        # ---- leads
        await pg.evaluate("""(()=>{const S=MSA.state;S.leads=[];['أحمد','سارة','منى'].forEach((n,i)=>S.leads.push({id:'l'+i,name:n,stage:'new',created:Date.now()-i,hist:[]}));MSA.save();MSA.go('leads')})()"""); await pg.wait_for_timeout(500)
        await pg.click('.gr-lead[data-id=l0] .gr-n', modifiers=['Control']); await pg.click('.gr-lead[data-id=l1] .gr-n', modifiers=['Control'])
        ok('leads: ctrl+click selects cards', set(await pg.evaluate("MSA.multi.ids('leads')"))=={'l0','l1'})
        stg = await pg.evaluate("MSA.state.leads[0].stage")
        await pg.click('.ms-bar [data-ms="a:stage"]'); await pg.wait_for_selector('.fm-ctx'); ids_ = await pg.evaluate("[...document.querySelectorAll('.fm-ctx [data-m^=\"st:\"]')].map(b=>b.dataset.m)")
        await pg.click('.fm-ctx [data-m="%s"]' % [i for i in ids_ if i!='st:'+stg][0]); await pg.wait_for_timeout(250)
        ok('leads: bulk stage change', await pg.evaluate("MSA.state.leads.filter(l=>l.stage!=='new').length===2"))
        await pg.click('.gr-lead[data-id=l2] .gr-n', button='right'); await pg.wait_for_selector('.fm-ctx')
        await pg.click('.fm-ctx [data-m=del]'); await pg.wait_for_selector('.overlay .mf .btn.primary'); await pg.click('.overlay .mf .btn.primary'); await pg.wait_for_timeout(300)
        ok('leads: right-click delete', await pg.evaluate("!MSA.state.leads.find(l=>l.id==='l2')&&MSA.state.leads.length===2"))
        # --- long press on touch + select button
        pt = await e.page(w=390, h=800); await pt.evaluate(SEED); await pt.wait_for_timeout(500)
        await pt.click('.ms-tgl'); await pt.wait_for_timeout(100)
        await pt.click('.trow[data-id=t1] .tt'); await pt.click('.trow[data-id=t2] .tt'); await pt.wait_for_timeout(100)
        ok('mobile: Select button turns on select mode and taps select', set(await sel(pt))=={'t1','t2'} and not await pt.query_selector('.drawer'))
        ok('mobile: bar fits the screen', await pt.evaluate("(()=>{const r=document.querySelector('.ms-bar').getBoundingClientRect();return r.left>=0&&r.right<=innerWidth+1&&document.documentElement.scrollWidth<=innerWidth+1})()"))
        await pt.click('.ms-bar [data-ms=clr]'); await pt.wait_for_timeout(100)
        ok('mobile: clear closes the bar', await sel(pt)==[] and not await pt.query_selector('.ms-bar'))
        await pt.evaluate("MSA.multi.clear('tasks')"); await pt.wait_for_timeout(100)
        await pt.evaluate("(()=>{const el=document.querySelector('.trow[data-id=t3]');const r=el.getBoundingClientRect();el.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerType:'touch',clientX:r.left+30,clientY:r.top+10}))})()"); await pt.wait_for_timeout(750)
        await pt.evaluate("document.querySelector('.trow[data-id=t3]').dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerType:'touch'}))")
        ok('mobile: long-press selects an item', await sel(pt)==['t3'] and not await pt.query_selector('.drawer'), await sel(pt))
        await pt.evaluate("MSA.multi.clear('tasks')")
        await pt.evaluate("(()=>{const el=document.querySelector('.trow[data-id=t3]');const r=el.getBoundingClientRect();el.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerType:'touch',clientX:r.left+30,clientY:r.top+10}));el.dispatchEvent(new PointerEvent('pointermove',{bubbles:true,pointerType:'touch',clientX:r.left+30,clientY:r.top+60}))})()"); await pt.wait_for_timeout(750)
        ok('mobile: scrolling (moving) cancels the long-press', await sel(pt)==[])
        pe = await e.page(w=1100, h=800, lang='en'); await pe.evaluate(SEED); await pe.wait_for_timeout(500)
        await pe.click('.trow[data-id=t1] .tt', modifiers=['Control'])
        ok('English: bar + toggle labels', await pe.evaluate("/selected/.test(document.querySelector('.ms-bar .ms-n').textContent)&&/Cancel select/.test(document.querySelector('.ms-tgl').textContent)"))
        errs = pg.errs + pt.errs + pe.errs; ok('no page errors', not errs, errs[:4])
    return summary()
sys.exit(asyncio.run(main()))
